BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Direction of testing: tracing from ledger tests existence
(1, 'Specific Areas and Transactions', 'Harmon & Associates is auditing Clearwater Retail''s accounts receivable. The engagement team selects balances from the subsidiary ledger and traces them to shipping documents and customer orders. What assertion is this procedure most likely designed to address?', '["Completeness of recorded receivables", "Valuation of the allowance for doubtful accounts", "Existence of recorded receivable balances", "Rights and obligations related to receivables"]'::jsonb, 2, 'Under AU-C 330, the direction of testing determines which assertion is addressed. Tracing from recorded amounts (the subsidiary ledger) to supporting evidence (shipping documents) tests existence, because the auditor is verifying that recorded items actually exist. Testing completeness requires the opposite direction—starting from source documents and tracing to the records. Choice A (completeness) would require selecting shipping documents first and verifying they were recorded.', 'medium', 3),

-- Q2: medium / L3 — Subsequent events: Type I adjustment vs Type II disclosure
(1, 'Specific Areas and Transactions', 'During fieldwork for Waverly Manufacturing''s December 31, 2025 audit, the engagement team at Preston & Partners learns on February 10, 2026 that a customer whose $340,000 receivable was outstanding at year-end filed for bankruptcy on January 15, 2026. How should this subsequent event most likely affect the financial statements?', '["Disclosed in the notes only, with no adjustment to the recorded receivable balance", "Adjusted in the financial statements because the bankruptcy provides additional evidence about conditions at the balance sheet date", "Ignored because the bankruptcy occurred after the balance sheet date", "Reported as a subsequent event only if the auditor''s report has not yet been issued"]'::jsonb, 1, 'Under AU-C 560, a Type I subsequent event provides additional evidence about conditions existing at the balance sheet date. The customer''s financial difficulties likely existed at December 31, 2025, and the January bankruptcy confirms those conditions. Therefore, the financial statements should be adjusted to reflect the impaired receivable. Choice A incorrectly treats this as a Type II event, which would apply only if the bankruptcy arose from conditions originating after year-end.', 'medium', 3),

-- Q3: hard / L4 — Evaluating whether to engage a specialist for Level 3 fair value
(1, 'Specific Areas and Transactions', 'Prescott & Associates is auditing Beacon Capital''s December 31, 2025 financial statements, which include $18 million in private equity investments measured at fair value using management''s internal valuation model with unobservable inputs. The engagement team lacks expertise in complex financial instrument valuation. The partner must decide the most appropriate course of action under AU-C 620.', '["Engage an auditor''s specialist with expertise in valuing private equity investments to assist in evaluating management''s model and assumptions", "Accept management''s valuations after confirming that the internal model was reviewed by the entity''s board of directors", "Request that management reclassify the investments from Level 3 to Level 2 to simplify the audit procedures", "Limit substantive testing to confirming the existence of the investments and disclose a scope limitation"]'::jsonb, 0, 'Under AU-C 620, when the audit team lacks specialized knowledge needed to evaluate complex fair value measurements, the auditor should engage a specialist. Level 3 fair values involving unobservable inputs and complex models require technical expertise the team acknowledges it lacks. Choice B is insufficient because board review does not substitute for independent audit evaluation of the valuation methodology and assumptions.', 'hard', 4),

-- Q4: easy / L1 — Dual-purpose test definition
(1, 'Specific Areas and Transactions', 'What is the primary characteristic of a dual-purpose test in auditing?', '["It tests the same assertion using two different audit procedures", "It applies the same procedure to two different account balances simultaneously", "It uses both inquiry and observation to test a single control", "It serves as both a test of controls and a substantive test in a single procedure"]'::jsonb, 3, 'A dual-purpose test simultaneously addresses two objectives: evaluating whether a control is operating effectively (test of controls) and detecting material misstatements in an amount or disclosure (substantive test). For example, inspecting a purchase order for an authorized signature tests the control while verifying the recorded amount tests the assertion. Choice A is incorrect because dual-purpose tests combine control and substantive objectives, not two procedures for one assertion.', 'easy', 1),

-- Q5: medium / L2 — Positive vs negative confirmation selection for AR
(1, 'Specific Areas and Transactions', 'Meridian & Co. is auditing Hartwell Distributors'' accounts receivable. The subsidiary ledger contains 2,400 customer accounts, including 85 accounts with balances exceeding $50,000 and 2,315 smaller routine balances. Under AU-C 505, which confirmation approach is most appropriate?', '["Send negative confirmations to all 2,400 accounts for comprehensive coverage", "Send positive confirmations for large and unusual balances and negative confirmations for a sample of smaller routine accounts", "Send positive confirmations only to the 85 large accounts and perform no procedures on smaller balances", "Substitute analytical procedures for all confirmation procedures because the account population is large"]'::jsonb, 1, 'Under AU-C 505, positive confirmations are appropriate for large, unusual, or higher-risk balances because non-responses require follow-up with alternative procedures. Negative confirmations are acceptable for smaller, routine balances when the auditor expects a low exception rate and believes recipients will respond to discrepancies. Choice A is inappropriate because negative confirmations alone provide less assurance for large balances where misstatement risk is higher.', 'medium', 2),

-- Q6: easy / L1 — Substantive analytical procedures definition
(1, 'Specific Areas and Transactions', 'Which of the following best describes a substantive analytical procedure?', '["An evaluation of financial information through analysis of plausible relationships among data", "A procedure that tests individual transactions for accuracy and authorization", "An inquiry of management about significant accounting policies", "A comparison of the current year''s financial statements to the prior year without further analysis"]'::jsonb, 0, 'Under AU-C 520, substantive analytical procedures evaluate financial information by analyzing plausible relationships among both financial and nonfinancial data to provide evidence about an assertion. They require the auditor to develop an expectation and investigate significant differences. Choice B describes tests of details rather than analytical procedures, which focus on relationships and patterns rather than individual item examination.', 'easy', 1),

-- Q7: medium / L2 — Inventory observation: tracing test counts to final listing
(1, 'Specific Areas and Transactions', 'During the physical inventory observation at Redstone Lumber on December 31, 2025, the audit team from Caldwell & Associates performs test counts of selected inventory items. After the count is completed, the auditor should:', '["Accept the final inventory listing without further procedures since the count was observed", "Recalculate all inventory extensions using the count tags from the day of the observation", "Trace the test count results to the final inventory listing to verify that observed quantities were accurately recorded", "Issue an inventory certificate based solely on the test count results"]'::jsonb, 2, 'Under AU-C 501, when the auditor observes physical inventory, the auditor performs test counts and then traces those counts to the final inventory compilation to ensure quantities observed were accurately reflected in the records. This step connects the observation evidence to the recorded amounts. Choice A is incorrect because observation alone is insufficient—the auditor must verify that the physical count results are properly incorporated into the final inventory listing.', 'medium', 2),

-- Q8: hard / L4 — Going concern plan feasibility with conditional financing
(1, 'Specific Areas and Transactions', 'Sterling Products'' December 31, 2025 financial statements are being audited by Ashford & Walsh. The company has recurring losses, negative cash flows, and a working capital deficit of $1.2 million. Management''s plan to mitigate going concern doubt relies on a $3 million credit facility renewal. The auditor obtains a letter from the bank indicating willingness to renew but subject to conditions the company has not yet met. Under AU-C 570, the auditor should:', '["Accept management''s plan as sufficient because the bank has expressed willingness to renew the facility", "Issue an adverse opinion because the company cannot demonstrate its ability to continue as a going concern", "Withdraw from the engagement because management''s plan contains too much uncertainty", "Conclude that substantial doubt is not alleviated because the financing is conditional and the conditions remain unmet, then evaluate the adequacy of the entity''s disclosures"]'::jsonb, 3, 'Under AU-C 570, the auditor must assess whether management''s plans are feasible and can be effectively implemented. A conditional credit facility with unmet conditions does not adequately alleviate substantial doubt. The auditor should conclude doubt remains and then determine whether disclosures are adequate—if so, an unmodified opinion with emphasis-of-matter is appropriate. Choice A is incorrect because a conditional commitment with unmet requirements does not provide sufficient mitigation of the going concern uncertainty.', 'hard', 4),

-- Q9: medium / L3 — Higher assessed risk shifts testing to year-end
(1, 'Specific Areas and Transactions', 'During risk assessment for Pinehurst Electronics'' audit, the engagement team at Boyd & Associates determines that revenue recognition carries a significantly higher risk of material misstatement than originally anticipated. What is the most likely effect on the timing of substantive procedures for revenue?', '["The auditor should perform revenue testing at or near the period end rather than at an interim date", "The auditor should accelerate testing to an interim date to identify misstatements earlier", "The auditor should defer revenue testing until after the financial statements are issued", "The timing of procedures is unaffected because only the nature of procedures changes in response to higher risk"]'::jsonb, 0, 'Under AU-C 330, when the assessed risk of material misstatement increases, the auditor responds by adjusting the nature, timing, and extent of substantive procedures. For timing, higher risk areas should be tested at or near year-end rather than at interim dates, because year-end testing provides stronger evidence about the balance at the reporting date. Choice B is incorrect because interim testing requires additional roll-forward procedures and provides less persuasive evidence for high-risk areas.', 'medium', 3),

-- Q10: medium / L3 — Kiting: analyzing the effect on reported cash
(1, 'Specific Areas and Transactions', 'While auditing Brentwood Supply''s cash accounts for December 31, 2025, the engagement team at Fischer & Co. discovers that a $275,000 check was drawn on Bank A on December 30 but not deposited into Bank B until January 3, 2026. However, both the disbursement from Bank A and the deposit into Bank B were recorded on December 30. What is the most likely effect on Brentwood''s reported cash balance?', '["Cash is understated by $275,000 because the disbursement was recorded prematurely", "Cash is correctly stated because the disbursement and deposit were recorded on the same date", "Cash is overstated by $275,000 because the deposit was recorded before it was actually made", "Cash is overstated by $550,000 because both the disbursement and deposit are misstated"]'::jsonb, 2, 'This describes check kiting—recording an interbank transfer deposit before it actually occurs to inflate the cash balance. The disbursement from Bank A on December 30 is properly recorded, but the deposit into Bank B was not made until January 3, meaning the December 30 deposit entry overstates cash by $275,000. Under AU-C 330, auditors test bank transfers near year-end specifically to detect kiting. Choice B is incorrect because the physical deposit did not occur until January 3, making the December 30 recording premature.', 'medium', 3),

-- Q11: medium / L2 — Search for unrecorded liabilities procedure
(1, 'Specific Areas and Transactions', 'Grant & Associates is auditing Fernwood Construction''s accounts payable as of December 31, 2025. To test the completeness of recorded liabilities, the auditor examines cash disbursements made during January 2026 and traces selected payments to the accounts payable subsidiary ledger at year-end. This procedure is designed to:', '["Verify that all recorded payables at year-end were valid obligations", "Identify liabilities that existed at year-end but were not recorded in the accounting records", "Confirm that cash disbursements in January were properly authorized", "Test the valuation of accounts payable balances at year-end"]'::jsonb, 1, 'Under AU-C 330, examining subsequent cash disbursements is a primary procedure for searching for unrecorded liabilities (testing completeness). If payments made after year-end relate to goods or services received before December 31, those obligations should have been recorded as payables at year-end. Choice A describes testing existence rather than completeness—existence testing would trace from the recorded ledger to supporting documents.', 'medium', 2),

-- Q12: hard / L4 — Roll-forward period with mid-year system change
(1, 'Specific Areas and Transactions', 'Chen & Partners performed interim substantive testing of Vanguard Logistics'' revenue account through September 30, 2025. In November, the auditor learns that Vanguard implemented a new revenue recognition system on October 1, replacing the prior system entirely. The engagement partner must determine the most appropriate response for the remaining audit procedures on the December 31, 2025 financial statements.', '["Perform substantive testing of the roll-forward period from October 1 through December 31 and evaluate the new system''s impact on the reliability of revenue recognition during that period", "Rely on the interim testing results through September 30 and limit year-end procedures to analytical review of the fourth quarter", "Withdraw from the engagement because the system change invalidates all prior audit work", "Reperform all interim testing from January 1 through December 31 using a completely new audit approach"]'::jsonb, 0, 'Under AU-C 330, when substantive procedures are performed at an interim date, the auditor must cover the roll-forward period with additional procedures. A significant system change during the roll-forward period requires the auditor to evaluate the new system''s impact on revenue recognition and perform substantive testing over the October–December period. Choice B is insufficient because analytical review alone does not adequately address the heightened risk from a system change during the roll-forward period.', 'hard', 4),

-- Q13: easy / L1 — Roll-forward period definition
(1, 'Specific Areas and Transactions', 'What is the roll-forward period in the context of an audit engagement?', '["The period from the date of the auditor''s report to the date financial statements are issued", "The period from the beginning of the fiscal year to the interim testing date", "The period from the prior year''s audit completion to the current year''s engagement start", "The period between an interim testing date and the balance sheet date"]'::jsonb, 3, 'The roll-forward period is the time span between when interim audit procedures are performed and the balance sheet date. Under AU-C 330, when substantive procedures are conducted before year-end, the auditor must perform additional procedures to extend the audit conclusions to the period-end balance. Choice A is incorrect because that describes the subsequent events period between the report date and financial statement issuance, not the roll-forward period.', 'easy', 1),

-- Q14: medium / L2 — Interest expense analytical procedure calculation
(1, 'Specific Areas and Transactions', 'While auditing Oakmont Industries'' December 31, 2025 financial statements, the engagement team at Blake & Associates develops an independent estimate of interest expense. Oakmont had average outstanding debt of $4,200,000 at a weighted-average rate of 5.8%. Oakmont recorded interest expense of $261,800. The auditor''s expected amount and appropriate conclusion are:', '["$243,600 expected; no investigation warranted because the difference is immaterial", "$210,000 expected; investigation warranted because the difference is $51,800", "$243,600 expected; further investigation is warranted because recorded interest exceeds the expectation by $18,200", "$261,800 expected; no investigation warranted because recorded and expected amounts agree"]'::jsonb, 2, 'Under AU-C 520, the auditor develops an independent expectation by multiplying average debt ($4,200,000) by the weighted-average rate (5.8%), yielding $243,600. The recorded amount of $261,800 exceeds the expectation by $18,200, which warrants investigation to determine whether the difference indicates a misstatement or results from factors not reflected in the estimate. Choice B uses an incorrect rate calculation ($4,200,000 × 5.0% = $210,000), not the stated weighted-average rate of 5.8%.', 'medium', 2),

-- Q15: medium / L3 — Effect of unreliable data on analytical procedure assurance
(1, 'Specific Areas and Transactions', 'During the audit of Calloway Services'' payroll expense, the engagement team at Harper & Klein uses headcount data from the HR system and average compensation rates to develop an independent estimate. However, the auditor discovers that the HR system data has not been reconciled to payroll records for six months. What is the most likely effect on the substantive analytical procedure?', '["The analytical procedure remains effective because the auditor developed the expectation independently of the accounting records", "The analytical procedure provides reduced assurance because the underlying data used to develop the expectation is unreliable", "The analytical procedure is invalid and the auditor must withdraw from the engagement", "The analytical procedure provides increased assurance because using a separate system creates independence from the financial statements"]'::jsonb, 1, 'Under AU-C 520, the effectiveness of a substantive analytical procedure depends on the reliability of the data used to develop the expectation. When the source data (HR headcount) has not been reconciled to payroll records for six months, its reliability is compromised, reducing the assurance the procedure provides. The auditor should consider alternative procedures or additional testing. Choice A is incorrect because independence of the data source does not compensate for the data''s unreliability.', 'medium', 3),

-- Q16: easy / L1 — Tests of details definition
(1, 'Specific Areas and Transactions', 'Which of the following best describes tests of details in an audit?', '["Procedures applied to individual transactions, balances, or disclosures to detect material misstatements", "Trend analyses comparing current year financial data to prior year amounts", "Inquiries of management regarding the design of internal controls", "Procedures that evaluate whether internal controls are operating effectively"]'::jsonb, 0, 'Under AU-C 330, tests of details are substantive procedures that examine individual transactions, account balances, or disclosures to detect material misstatements at the assertion level. They differ from substantive analytical procedures, which evaluate relationships among financial data. Choice D describes tests of controls, not tests of details—tests of controls assess the operating effectiveness of controls rather than testing financial statement amounts directly.', 'easy', 1),

-- Q17: easy / L1 — Bank reconciliation audit procedure
(1, 'Specific Areas and Transactions', 'Which procedure is most directly related to auditing bank reconciliations?', '["Sending positive confirmations to the entity''s major customers", "Observing the physical inventory count at the entity''s warehouse", "Tracing reconciling items on the bank reconciliation to supporting documentation", "Recomputing depreciation expense based on the fixed asset register"]'::jsonb, 2, 'Under AU-C 330, auditing bank reconciliations involves tracing reconciling items (outstanding checks, deposits in transit, bank charges) to supporting documentation to verify that the reconciliation properly explains differences between the bank statement and the general ledger cash balance. Choice A relates to accounts receivable testing, not cash—customer confirmations verify receivable balances rather than bank account reconciliations.', 'easy', 1),

-- Q18: medium / L2 — Revenue cutoff testing procedure
(1, 'Specific Areas and Transactions', 'Walsh & Patel is auditing Crestview Manufacturing''s revenue for the year ended December 31, 2025. To test revenue cutoff, the engagement team selects a sample of shipping documents from the last five days of December 2025 and the first five days of January 2026. The auditor should trace these shipping documents to:', '["The accounts receivable aging schedule to verify collection timing", "The purchase order files to confirm that the goods were ordered by customers", "The bank deposit records to verify that payment was received before year-end", "The sales journal to verify that revenue was recorded in the correct accounting period"]'::jsonb, 3, 'Under AU-C 330, revenue cutoff testing verifies that sales are recorded in the proper period. The auditor selects shipping documents around year-end and traces them to the sales journal to confirm that December shipments were recorded in December and January shipments were recorded in January. Choice C is incorrect because revenue recognition depends on when goods were shipped and control transferred, not on when payment was received.', 'medium', 2),

-- Q19: hard / L3 — Estimate within auditor's range evaluation
(1, 'Specific Areas and Transactions', 'During the audit of Pemberton Healthcare''s December 31, 2025 financial statements, the engagement team at Sullivan & Cross evaluates a $4.5 million medical malpractice liability estimate. The auditor''s independent estimate yields a reasonable range of $3.8 million to $5.1 million. Management recorded $3.9 million, near the low end. The auditor also notes that management selected the low end of reasonable ranges for three other significant estimates. Under AU-C 540, the auditor should conclude that:', '["Management''s estimate is unreasonable because it falls below the midpoint of the auditor''s range and likely reflects management bias", "Management''s estimate is within the auditor''s reasonable range and is therefore not materially misstated, although the auditor should remain alert to patterns of estimates at the low end of ranges across other accounts", "Management''s estimate must be adjusted to the midpoint of the auditor''s range to eliminate potential bias", "Management''s estimate should be disallowed entirely because the reasonable range exceeds 10% of the recorded amount"]'::jsonb, 1, 'Under AU-C 540, when the auditor develops a range, any point within that range is considered reasonable. Management''s $3.9 million estimate falls within the $3.8M–$5.1M range and is therefore acceptable. However, the auditor should evaluate whether a pattern of estimates consistently at the low end across multiple accounts indicates management bias. Choice A is incorrect because falling below the midpoint alone does not make an estimate unreasonable—the entire range represents acceptable outcomes.', 'hard', 3),

-- Q20: medium / L2 — Alternative procedures for confirmation non-responses
(1, 'Specific Areas and Transactions', 'During the accounts receivable confirmation process for Ashford Wholesalers, the engagement team at Greystone & Partners sent positive confirmations to 60 customers. After second requests, 12 customers have not responded. Under AU-C 505, the auditor should:', '["Perform alternative procedures such as examining subsequent cash receipts and shipping documentation for the non-responding accounts", "Treat all non-responses as confirmation of the recorded balance since no exceptions were noted", "Issue a scope limitation in the audit report for the unconfirmed portion of receivables", "Remove the non-responding accounts from the sample and increase the sample of confirmed accounts proportionally"]'::jsonb, 0, 'Under AU-C 505, when positive confirmations are not returned, the auditor must perform alternative procedures to obtain sufficient evidence about the assertions being tested. Common alternatives include examining subsequent cash receipts, reviewing shipping documents, and inspecting sales invoices. Choice B is incorrect because non-response to a positive confirmation does not constitute evidence—unlike negative confirmations, positive confirmations require an explicit reply.', 'medium', 2),

-- Q21: easy / L2 — Inventory obsolescence reserve evaluation
(1, 'Specific Areas and Transactions', 'Thornton & Associates is auditing Lakewood Electronics'' inventory reserve for obsolescence as of December 31, 2025. The engagement team notes that $890,000 of inventory has not moved in over 18 months. To evaluate the reasonableness of management''s obsolescence reserve, the auditor should:', '["Accept the reserve as stated because slow-moving inventory does not necessarily require a write-down", "Request that management write off all inventory older than 12 months to eliminate obsolescence risk", "Confirm the physical existence of the slow-moving inventory through bank confirmation", "Review historical turnover rates, recent sales activity, and management''s plans for the slow-moving items"]'::jsonb, 3, 'Under AU-C 540, the auditor evaluates accounting estimates by reviewing the data and assumptions management used. For an obsolescence reserve, the auditor examines historical turnover rates, recent sales of similar items, and management''s disposition plans to assess whether the reserve is reasonable. Choice A is incorrect because slow-moving inventory lasting 18 months without movement is a significant indicator of potential obsolescence requiring audit evaluation, not acceptance without procedures.', 'easy', 2),

-- Q22: easy / L1 — Completeness assertion: tracing from source documents
(1, 'Specific Areas and Transactions', 'Tracing from source documents to the accounting records primarily tests which assertion?', '["Existence of recorded transactions", "Completeness of recorded transactions", "Valuation of account balances", "Presentation and disclosure"]'::jsonb, 1, 'Under AU-C 330, the direction of testing determines which assertion is addressed. Tracing from source documents (such as shipping documents or receiving reports) to the accounting records tests completeness because it verifies that valid transactions were actually recorded. Choice A is incorrect because testing existence requires the opposite direction—selecting from recorded amounts and tracing back to supporting source documents.', 'easy', 1),

-- Q23: easy / L1 — Extent of substantive procedures definition
(1, 'Specific Areas and Transactions', 'In audit planning, the extent of substantive procedures primarily refers to which factor?', '["The type and purpose of the audit procedure selected", "The date on which the audit procedure is performed", "The amount of testing performed, such as sample size or volume of data analyzed", "The qualifications of the audit staff assigned to perform the procedure"]'::jsonb, 2, 'Under AU-C 330, the extent of substantive procedures refers to how much testing is performed—the sample size, number of observations, or amount of data analyzed. Greater extent means more items tested, providing more evidence. Choice A describes the nature of the procedure (its type and purpose), and choice B describes the timing, which are the other two dimensions the auditor adjusts in response to assessed risks.', 'easy', 1),

-- Q24: medium / L2 — Payroll analytical procedure: developing an independent estimate
(1, 'Specific Areas and Transactions', 'During the audit of Sherwood Services'' payroll expense, the engagement team at Burke & Associates obtains data showing an average of 245 employees during 2025 with an average annual compensation of $62,400. Sherwood recorded total payroll expense of $15,588,000. The auditor''s independently calculated expectation is:', '["$15,288,000, which is $300,000 less than the recorded amount and warrants investigation", "$15,588,000, which agrees with the recorded amount and requires no further testing", "$14,400,000, which is $1,188,000 less than the recorded amount", "$16,100,000, which exceeds the recorded amount by $512,000"]'::jsonb, 0, 'Under AU-C 520, the auditor develops an independent expectation for payroll by multiplying average headcount (245) by average compensation ($62,400), yielding $15,288,000. The recorded amount of $15,588,000 exceeds this by $300,000, warranting investigation into whether the difference results from overtime, bonuses, or a misstatement. Choice B is incorrect because 245 × $62,400 = $15,288,000, not $15,588,000, so the amounts do not agree.', 'medium', 2),

-- Q25: easy / L1 — Substantive procedures always required for material accounts
(1, 'Specific Areas and Transactions', 'Under auditing standards, when must the auditor perform substantive procedures?', '["Only when controls are found to be ineffective during testing", "Only when the assessed risk of material misstatement is high", "Only for accounts where management has made significant estimates", "For every material class of transactions, account balance, and disclosure regardless of assessed risk"]'::jsonb, 3, 'Under AU-C 330, substantive procedures are required for all material classes of transactions, account balances, and disclosures, regardless of the assessed level of risk. Even when controls are tested and found effective, substantive procedures cannot be eliminated entirely. Choice A is incorrect because the requirement to perform substantive procedures applies universally to material accounts—not only when controls are ineffective.', 'easy', 1),

-- Q26: medium / L2 — AR aging and allowance for doubtful accounts evaluation
(1, 'Specific Areas and Transactions', 'Wallace & Reed is auditing Eastbrook Medical Supply''s allowance for doubtful accounts as of December 31, 2025. The accounts receivable aging shows $1.4 million in balances over 90 days past due. Management recorded a $280,000 allowance based on a 20% historical loss rate. To evaluate this estimate, the auditor should:', '["Accept the allowance because the 20% rate is consistently applied across all aging categories", "Test the underlying data by reviewing the aging schedule accuracy and evaluating whether the historical loss rate reflects current economic conditions and specific customer circumstances", "Require management to increase the allowance to 50% of aged balances as a conservative approach", "Confirm the aged balances directly with the customers to verify their ability to pay"]'::jsonb, 1, 'Under AU-C 540, the auditor evaluates accounting estimates by testing the data, assumptions, and methodology management used. For the allowance, this includes verifying the accuracy of the aging schedule and assessing whether the historical loss rate remains appropriate given current conditions and individual customer situations. Choice A is incorrect because consistent application of a rate does not guarantee its reasonableness—the rate itself must be evaluated against current evidence.', 'medium', 2),

-- Q27: hard / L4 — Subsequent event discovered after report date but before issuance
(1, 'Specific Areas and Transactions', 'Bradford & Associates issued its audit report on Creekside Ventures'' December 31, 2025 financial statements on March 1, 2026. On March 10, before the financial statements were issued to shareholders on March 20, the auditor learns that Creekside''s largest warehouse was destroyed by fire on March 5. The uninsured loss is estimated at $6.2 million, representing 40% of total assets. The engagement partner must evaluate the appropriate treatment.', '["No action is required because the fire occurred after the audit report date and the auditor has no further responsibility", "Adjust the December 31, 2025 financial statements to reflect the $6.2 million loss because it is material", "Evaluate whether the entity has disclosed the fire as a Type II subsequent event in the notes and consider the impact on going concern, since the financial statements have not yet been issued", "Require Creekside to delay issuance of the financial statements until the insurance claim is resolved"]'::jsonb, 2, 'Under AU-C 560, facts discovered after the report date but before the financial statements are issued require the auditor to evaluate whether the statements need revision. A March 5 fire is a Type II subsequent event (new conditions after year-end) requiring note disclosure rather than adjustment. Given the 40% asset loss, the auditor should also evaluate going concern implications. Choice A is incorrect because the auditor has a responsibility for subsequent events through the financial statement issuance date, not just the report date.', 'hard', 4),

-- Q28: medium / L3 — Sample size reduction increases detection risk
(1, 'Specific Areas and Transactions', 'During planning for Ridgeway Automotive''s audit, the engagement team at Harper & Wells reduces the planned sample size for testing accounts payable from 80 items to 40 items because of time constraints. What is the most likely effect of this change on the audit?', '["Detection risk decreases because a smaller sample is easier to examine thoroughly", "Inherent risk increases because the auditor is performing fewer procedures", "Control risk changes to compensate for the reduced sample size", "Detection risk increases because the smaller sample provides less evidence to detect material misstatements"]'::jsonb, 3, 'Under AU-C 330, the extent of substantive procedures (sample size) directly affects detection risk. A smaller sample provides less evidence, increasing the probability that the auditor will fail to detect a material misstatement that exists. This raises detection risk. Choice A is incorrect because thoroughness of examining individual items does not offset the reduced population coverage—detection risk depends on how much of the population is tested, not how carefully each item is examined.', 'medium', 3),

-- Q29: hard / L4 — Assess management bias across multiple estimates
(1, 'Specific Areas and Transactions', 'During the audit of Whitfield Properties'' December 31, 2025 financial statements, the engagement team at Drake & Sawyer evaluates a $7.8 million impairment estimate for a commercial real estate portfolio. The auditor develops a range of $6.5 million to $9.2 million. Management selected $6.6 million, near the low end. Across four other significant estimates, management also selected amounts at the low end of reasonable ranges. Under AU-C 540, the auditor should:', '["Evaluate whether the pattern of selecting low-end estimates across multiple accounts constitutes management bias and consider the cumulative effect on the financial statements as a whole", "Accept each individual estimate because every point within the auditor''s range is equally acceptable regardless of patterns", "Require management to adjust all five estimates to the midpoints of their respective ranges", "Issue a qualified opinion solely because management selected the low end of the impairment range"]'::jsonb, 0, 'Under AU-C 540, the auditor must evaluate indicators of possible management bias, including patterns where management consistently selects estimates at one end of the reasonable range. While each individual estimate may be reasonable, the cumulative effect of consistently selecting the low end across multiple estimates may result in a material misstatement of the financial statements taken as a whole. Choice B is incorrect because it ignores the requirement to assess bias across multiple estimates, not just individually.', 'hard', 4),

-- Q30: medium / L3 — Precision of expectation in analytical procedures
(1, 'Specific Areas and Transactions', 'During the audit of Maplewood Leasing''s rent expense, the engagement team at Carlisle & Associates compares total rent expense to the prior year amount and notes a 3% increase consistent with market trends. For depreciation expense, the team calculates an expected amount using the detailed fixed asset register, depreciation methods, and useful lives. Which analytical procedure provides greater assurance?', '["The rent expense procedure provides greater assurance because comparing to prior year is a well-established audit technique", "The depreciation procedure provides greater assurance because it uses a more precise expectation based on disaggregated data and known variables", "Both procedures provide equivalent assurance because they are both substantive analytical procedures", "Neither procedure provides meaningful assurance because analytical procedures are supplementary to tests of details"]'::jsonb, 1, 'Under AU-C 520, the assurance provided by a substantive analytical procedure depends on the precision of the auditor''s expectation. A precise expectation using detailed data (fixed asset register, methods, useful lives) provides significantly more assurance than a general comparison to the prior year, which is a low-precision expectation with many possible explanations for changes. Choice A is incorrect because prior-year comparison alone develops a vague expectation that could mask material misstatements.', 'medium', 3)
;

COMMIT;
